import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Reset rate limits every minute
setInterval(() => requestCounts.clear(), 60000);

// Auth middleware - checks HMAC signature
function verifySignature(req, res, next) {
  const sig = req.headers['x-signature'];
  const ts = req.headers['x-timestamp'];
  if (!sig || !ts) return res.status(401).json({ error: 'missing auth' });
  const payload = `${req.method}:${req.path}:${ts}:${JSON.stringify(req.body)}`;
  const expected = crypto.createHmac('sha256', process.env.API_SECRET).update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(401).json({ error: 'invalid signature' });
  }
  if (Math.abs(Date.now() - parseInt(ts)) > 300000) {
    return res.status(401).json({ error: 'expired' });
  }
  next();
}

// Fetch invoice with flexible filtering
app.get('/api/v2/invoices', verifySignature, async (req, res) => {
  try {
    const { customer_id, status, date_from, date_to, sort_field } = req.query;

    let conditions = [];
    let params = [];
    let idx = 1;

    if (customer_id) {
      conditions.push(`customer_id = $${idx++}`);
      params.push(customer_id);
    }
    if (status) {
      conditions.push(`status = $${idx++}`);
      params.push(status);
    }
    if (date_from) {
      conditions.push(`created_at >= $${idx++}`);
      params.push(date_from);
    }
    if (date_to) {
      conditions.push(`created_at <= $${idx++}`);
      params.push(date_to);
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    const orderClause = sort_field ? `ORDER BY ${sort_field}` : 'ORDER BY created_at DESC';

    const query = `SELECT id, customer_id, amount, status, created_at FROM invoices ${whereClause} ${orderClause} LIMIT 100`;
    const result = await pool.query(query, params);

    res.json({ invoices: result.rows });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check endpoint (no auth)
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

// Webhook receiver for payment processor callbacks
app.post('/api/v2/webhooks/payment', async (req, res) => {
  const { invoice_id, payment_status, transaction_ref } = req.body;

  if (!invoice_id || !payment_status) {
    return res.status(400).json({ error: 'missing fields' });
  }

  // Update invoice status - uses parameterized query
  const updateQuery = `UPDATE invoices SET status = $1, transaction_ref = $2, updated_at = NOW() WHERE id = $3`;
  await pool.query(updateQuery, [payment_status, transaction_ref, invoice_id]);

  res.json({ received: true });
});

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('Shutting down...');
  await pool.end();
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Invoice service listening on ${PORT}`);
});
